import { sortBy } from "../../utils/function-helper";
const QUERY_TIMEOUT_MS = 30000;

type HandlerStreamObserver = {
	next?: (value: [unknown[], number]) => void;
	complete?: () => void;
};

type HandlerStreamSubscription = {
	unsubscribe(): void;
};

const createErrorResult = (error) => [{ error }];

const runQueryHandler = (
	options,
	handlerMod,
	onResults,
	onComplete,
	isCancelled,
) => {
	let finished = false;

	const finish = () => {
		if (finished) {
			return;
		}

		finished = true;
		clearTimeout(timeoutId);
		onComplete();
	};

	const emitResults = (results) => {
		if (finished || isCancelled()) {
			return;
		}

		onResults(results);
	};

	const timeoutId = window.setTimeout(() => {
		emitResults(createErrorResult({ message: "Request has timed out." }));
		finish();
	}, QUERY_TIMEOUT_MS);

	Promise.resolve()
		.then(() =>
			handlerMod(options, {
				send(data) {
					emitResults(data);
					finish();
				},
				sendPartial(data) {
					emitResults(data);
				},
				error(error) {
					console.error("Query handler errored", error);
					emitResults(createErrorResult(error));
					finish();
				},
				complete() {
					finish();
				},
			}),
		)
		.catch((err) => {
			console.error("Query handler errored", err);
			emitResults(createErrorResult(err));
			finish();
		});

	return () => {
		finished = true;
		clearTimeout(timeoutId);
	};
};

const concatResults = ([accResults, processedCount], newResults) => {
	return [sortBy(accResults.concat(newResults), "id"), processedCount + 1];
};

/**
 *
 * @param data array of queryHandlers of type {q: function}
 * @param options {queryText: string, limit: number, typeFilter: string}
 * @returns the modified queryHandler collection as a subscribable stream
 */
export const handler = (data, options) => {
	return {
		subscribe(observer: HandlerStreamObserver): HandlerStreamSubscription {
			const queryHandlers = data.filter((value) => typeof value === "function");
			let cancelled = false;
			let accResults = [];
			let processedCount = 0;
			let pendingHandlers = queryHandlers.length;

			if (!pendingHandlers) {
				observer.complete?.();
				return {
					unsubscribe() {
						cancelled = true;
					},
				};
			}

			const cleanups = queryHandlers.map((queryHandler) =>
				runQueryHandler(
					{ ...options },
					queryHandler,
					(results) => {
						if (cancelled) {
							return;
						}

						[accResults, processedCount] = concatResults(
							[accResults, processedCount],
							results,
						);
						observer.next?.([accResults, processedCount]);
					},
					() => {
						if (cancelled) {
							return;
						}

						pendingHandlers -= 1;
						if (pendingHandlers === 0) {
							observer.complete?.();
						}
					},
					() => cancelled,
				),
			);

			return {
				unsubscribe() {
					cancelled = true;
					cleanups.forEach((cleanup) => cleanup());
				},
			};
		},
	};
};

export const handleArrowDown = (
	searchResult,
	selectedItem,
	showAllActiveGroupId,
	limit,
) => {
	let updatedSelectedItem = { id: undefined, group: undefined };

	if (!selectedItem || !selectedItem.group) {
		// User just typed query
		updatedSelectedItem = {
			group: searchResult[0]?.id,
			...searchResult[0]?.resultItems[0],
		};
		return updatedSelectedItem;
	}

	const groupIndex = searchResult
		?.map((item) => item?.id)
		.indexOf(selectedItem?.group);
	const group = searchResult[groupIndex];
	const itemIndex = group?.resultItems
		?.map((item) => item.id)
		.indexOf(selectedItem?.id);

	if (itemIndex === -1) {
		// If the item index is -1, select the first item of the next group
		if (groupIndex < searchResult?.length - 1) {
			updatedSelectedItem = {
				group: searchResult[groupIndex + 1]?.id,
				...searchResult[groupIndex + 1]?.resultItems[0],
			};
		} else {
			updatedSelectedItem = {
				group: searchResult[0]?.id,
				...searchResult[0]?.resultItems[0],
			};
		}
	} else {
		// Handle expanded group case
		if (showAllActiveGroupId === group.id) {
			if (itemIndex < group?.resultItems?.length - 1) {
				updatedSelectedItem = {
					group: group?.id,
					...group?.resultItems[itemIndex + 1],
				};
			} else {
				updatedSelectedItem = {
					group: group?.id,
					...group?.resultItems[0], // Wrap around to the first item
				};
			}
		} else {
			// Default navigation
			if (itemIndex < limit - 1 && itemIndex < group?.resultItems?.length - 1) {
				updatedSelectedItem = {
					group: group?.id,
					...group?.resultItems[itemIndex + 1],
				};
			} else if (itemIndex === group?.resultItems?.length - 1) {
				if (groupIndex < searchResult?.length - 1) {
					updatedSelectedItem = {
						group: searchResult[groupIndex + 1]?.id,
						...searchResult[groupIndex + 1]?.resultItems[0],
					};
				} else {
					updatedSelectedItem = {
						group: searchResult[0]?.id,
						...searchResult[0]?.resultItems[0],
					};
				}
			} else {
				updatedSelectedItem = {
					group: group.id,
					id: "show_all",
				};
			}
		}
	}

	// Handle "More Results..." button click
	if (
		showAllActiveGroupId &&
		selectedItem?.id === "show_all" &&
		selectedItem?.group === group?.id
	) {
		updatedSelectedItem = {
			group: group?.id,
			...group?.resultItems[0],
		};
	}

	return updatedSelectedItem;
};

export const handleArrowUp = (
	searchResult,
	selectedItem,
	showAllActiveGroupId,
	limit,
) => {
	let updatedSelectedItem = { id: undefined, group: undefined };

	if (!selectedItem || !selectedItem?.group) {
		// User just pressed the up arrow for the first time
		const lastGroup = searchResult[searchResult.length - 1];
		if (lastGroup?.resultItems?.length > limit) {
			updatedSelectedItem = {
				group: lastGroup?.id,
				id: "show_all",
			};
		} else {
			updatedSelectedItem = {
				group: lastGroup?.id,
				...lastGroup?.resultItems[lastGroup?.resultItems?.length - 1],
			};
		}
		return updatedSelectedItem;
	}

	const groupIndex = searchResult?.findIndex(
		(item) => item?.id === selectedItem?.group,
	);
	const group = searchResult[groupIndex];
	const itemIndex = group?.resultItems.findIndex(
		(item) => item?.id === selectedItem?.id,
	);
	const isExpandedGroup = showAllActiveGroupId === group?.id;
	const groupItemsToShow = isExpandedGroup
		? group?.resultItems?.length
		: Math.min(group?.resultItems?.length, limit);

	if (itemIndex > 0) {
		// Navigate within the group
		updatedSelectedItem = {
			group: group?.id,
			...group?.resultItems[itemIndex - 1],
		};
	} else if (selectedItem?.id === "show_all") {
		// If "More Results..." is selected, navigate to the last item of the current group
		updatedSelectedItem = {
			group: group?.id,
			...group?.resultItems[groupItemsToShow - 1],
		};
	} else if (itemIndex === 0 && !isExpandedGroup) {
		// Navigate to the "More Results..." link of the previous group
		const newGroupIndex =
			groupIndex > 0 ? groupIndex - 1 : searchResult?.length - 1;
		const newGroup = searchResult[newGroupIndex];
		const newGroupItemsToShow =
			showAllActiveGroupId === newGroup?.id
				? newGroup?.resultItems?.length
				: Math.min(newGroup?.resultItems?.length, limit);
		if (newGroupItemsToShow < limit) {
			updatedSelectedItem = {
				group: newGroup?.id,
				...newGroup?.resultItems[newGroupItemsToShow - 1],
			};
		} else {
			updatedSelectedItem = {
				group: newGroup?.id,
				id: "show_all",
			};
		}
	} else if (isExpandedGroup) {
		// Trapping focus within the expanded group
		updatedSelectedItem = {
			group: group?.id,
			...group?.resultItems[group?.resultItems?.length - 1],
		};
	}

	return updatedSelectedItem;
};
